function runAgent(args, stdin) {
  const opts = { stdout: "pipe", stderr: "pipe" }
  if (stdin) {
    const tmpFile = join(tmpdir(), `tp-${Date.now()}.json`)
    writeFileSync(tmpFile, stdin)
    opts.stdin = Bun.file(tmpFile)
    const result = Bun.spawnSync([TERRAPHIM_AGENT, ...args], opts)
    try { unlinkSync(tmpFile) } catch {}
    return result
  }
  return Bun.spawnSync([TERRAPHIM_AGENT, ...args], opts)
}

function extractExitCode(rawOutput, metadata) {
  if (typeof metadata?.exitCode === "number") return metadata.exitCode
  if (typeof metadata?.exit_code === "number") return metadata.exit_code
  const m = String(rawOutput).match(/exit code[: ]+([0-9]+)/i)
  if (m) return parseInt(m[1], 10)
  const s = String(rawOutput)
  if (s.includes("command not found") || s.includes("error:") || s.includes("Error:") || s.includes("FAILED")) return 1
  return 0
}

